from content_helpers import code, output, choice, lesson, section, program
from content_06 import with_functions, example

def sections():
    return [section("projects", "15. Самостоятельные проекты", "Соберите консольные инструменты с понятным протоколом и состоянием.", [
        lesson("console", "Проект: командный пульт", "Отделите команды, состояние и ответы.",
            "Консольное меню может работать без графических кнопок: программа читает команды и обновляет состояние. Протокол задаёт точные слова, аргументы и формат ответа. В этом проекте команда ADD x добавляет число, TOTAL печатает сумму, STOP завершает работу. Чтение std::string command в while(cin>>command) прекращается и при конце входа.\n\nРешайте отдельно: что хранится, какая команда что меняет, какое сообщение печатается. Не добавляйте приветствия, если протокол их не просит. Используйте функции для вычислений и main для взаимодействия. На нераспознанную команду проект отвечает Invalid и завершается, не пытаясь догадаться о намерении пользователя.\n\nДля каждого сценария проверьте пустой журнал, несколько команд и завершение без дополнительного вывода.",
            program('std::string command;\nint sum = 0;\nwhile (std::cin >> command) {\n    if (command == "STOP") { break; }\n    if (command == "TOTAL") { std::cout << sum << "\\n"; }\n    else if (command == "ADD") { int x = 0; std::cin >> x; sum += x; }\n    else { std::cout << "Invalid\\n"; break; }\n}', "iostream string"),
            "Протокол — контракт между частями системы. Реальное приложение тоже должно различать команду пользователя, сохранённое состояние и результат проверки. Нельзя выдавать неподдерживаемую команду за успешно выполненное действие. В учебных проектах корректность аргументов явно ограничена, а защищённый произвольный ввод требует дополнительных проверок.",
            "Нарисуйте таблицу команд: аргументы → изменение состояния → ответ. Каждая видимая команда должна реально работать.", [
                code("pult", "Пульт накопителя", 'Реализуйте протокол: ADD x (x от −100 до 100) добавляет к сумме, TOTAL печатает сумму с переносом, STOP завершает. Неизвестная команда печатает Invalid с переносом и завершает. До 100 команд; аргументы известных команд корректны.', 'std::string command;\nint sum = 0;\nwhile (std::cin >> command) {\n    if (command == "STOP") { break; }\n    if (command == "ADD") { int x = 0; std::cin >> x; sum += x; }\n    else if (command == "TOTAL") { std::cout << sum << "\\n"; }\n    else { std::cout << "Invalid\\n"; break; }\n}', [("TOTAL ADD 7 ADD -2 TOTAL STOP", "0\n5\n"), ("STOP", ""), ("BOGUS", "Invalid\n"), ("ADD 5 TOTAL ADD -10 TOTAL STOP", "5\n-5\n"), ("ADD 100 ADD 100 TOTAL STOP", "200\n"), ("TOTAL TOTAL STOP", "0\n0\n"), ("ADD -100 TOTAL STOP", "-100\n")], ["Сумма живёт между командами.", "ADD не печатает ответ; TOTAL не меняет состояние."], "Разделение команд проверяется сценарием из нескольких шагов, не только одиночным вызовом.", headers="iostream string", difficulty=3),
                code("undo", "Отмена последнего числа", 'Команды: ADD x добавляет число в vector; UNDO удаляет последний через pop_back, если он есть; COUNT печатает размер с переносом; STOP завершает. До 100 корректных команд, x (−100…100). UNDO для пустого набора ничего не делает.', 'std::vector<int> values;\nstd::string command;\nwhile (std::cin >> command) {\n    if (command == "STOP") { break; }\n    if (command == "ADD") { int x = 0; std::cin >> x; values.push_back(x); }\n    else if (command == "UNDO") { if (!values.empty()) { values.pop_back(); } }\n    else if (command == "COUNT") { std::cout << values.size() << "\\n"; }\n}', [("UNDO COUNT ADD 7 ADD 2 UNDO COUNT STOP", "0\n1\n"), ("ADD 1 UNDO UNDO COUNT STOP", "0\n"), ("COUNT ADD 5 COUNT UNDO COUNT STOP", "0\n1\n0\n"), ("UNDO UNDO STOP", ""), ("ADD 1 ADD 2 ADD 3 UNDO UNDO COUNT STOP", "1\n"), ("COUNT STOP", "0\n")], ["pop_back удаляет последний существующий элемент и уменьшает размер.", "Перед pop_back обязательно проверьте !values.empty()."], "Операция отмены имеет отдельный безопасный контракт для пустого состояния.", headers="iostream string vector", difficulty=3),
                choice("protocol", "Лишний вывод", 'Автотест протокола ожидает только ответы на TOTAL. Можно ли добавить перед каждой командой «Введите команду:» без изменения контракта?', ["Нет, это дополнительный вывод, которого протокол не допускает", "Да, любые подсказки автоматически игнорируются", "Да, если подсказка по-русски"], 0, ["Протокол определяет весь наблюдаемый текст.", "Удобство ручного интерфейса и машинный формат — разные режимы."], "Если нужны приглашения, их нужно явно включить в формат или отдельный интерактивный режим."),
                code("state", "Сумма после отмены", 'Расширьте пульт: ADD x сохраняет число, UNDO убирает последнее, TOTAL печатает сумму всех сохранённых, STOP завершает. До 100 корректных команд, x (−100…100). Пустой UNDO ничего не меняет.', 'std::vector<int> values;\nstd::string command;\nint sum = 0;\nwhile (std::cin >> command) {\n    if (command == "STOP") { break; }\n    if (command == "ADD") {\n        int x = 0; std::cin >> x; values.push_back(x); sum += x;\n    } else if (command == "UNDO") {\n        if (!values.empty()) { sum -= values.back(); values.pop_back(); }\n    } else if (command == "TOTAL") { std::cout << sum << "\\n"; }\n}', [("ADD 7 ADD -2 TOTAL UNDO TOTAL UNDO TOTAL STOP", "5\n7\n0\n"), ("UNDO TOTAL STOP", "0\n"), ("ADD 5 ADD 10 TOTAL UNDO TOTAL UNDO UNDO TOTAL STOP", "15\n5\n0\n"), ("UNDO UNDO TOTAL STOP", "0\n"), ("ADD -5 ADD 5 TOTAL STOP", "0\n"), ("ADD 100 TOTAL UNDO TOTAL STOP", "100\n0\n")], ["back читает последний элемент, pop_back удаляет его.", "Вычитайте значение из суммы до удаления."], "Инвариант: sum равен сумме текущего vector после каждой команды.", headers="iostream string vector", difficulty=3)
            ], ["проект", "команды", "состояние"]),
        lesson("analysisproject", "Проект: анализатор измерений", "Постройте проверяемый отчёт из нескольких вычислений.",
            "Законченный анализатор сначала читает данные, затем вычисляет характеристики, затем выводит отчёт в одном формате. Не меняйте исходный порядок ради одной характеристики, если он нужен для другой. Для частот используйте map, для медианы — отсортированную копию, для суммы — широкий накопитель.\n\nСоглашения о пустом наборе и ничьих — часть проекта. Если медиана определена только для нечётного непустого набора, прямо ограничьте вход. Для наиболее частого значения можно решить ничью выбором меньшего ключа. Map помогает этим порядком, но заменять лучший результат нужно только при строго большей частоте.\n\nРезультат не считается верным только потому, что выглядит правдоподобно: проверьте каждый показатель отдельно.",
            program('std::map<int, int> counts;\n++counts[3]; ++counts[1]; ++counts[3];\nint bestValue = counts.begin()->first;\nint bestCount = 0;\nfor (const auto& entry : counts) {\n    if (entry.second > bestCount) { bestValue = entry.first; bestCount = entry.second; }\n}\nstd::cout << bestValue;', "iostream map"),
            "Сортировка и частоты отвечают на разные вопросы. Мода — наиболее частое значение, медиана — центральное после упорядочения, среднее — сумма, делённая на число. Они могут совпасть на простом наборе и сильно различаться на другом. Выбирайте тесты, различающие определения.",
            "Разделяйте показатели и явно определяйте ничьи. Не используйте один удачный набор как доказательство всех расчётов.", [
                code("mode", "Наиболее частое значение", 'Ввод: n (1…100), n целых (−100…100). Выведите наиболее частое значение; при равной частоте выберите меньшее.', 'int n = 0;\nstd::cin >> n;\nstd::map<int, int> counts;\nfor (int i = 0; i < n; ++i) { int x = 0; std::cin >> x; ++counts[x]; }\nint best = 0, frequency = 0;\nfor (const auto& entry : counts) {\n    if (entry.second > frequency) { best = entry.first; frequency = entry.second; }\n}\nstd::cout << best;', [("6 3 1 3 1 9 9", "1"), ("1 -7", "-7"), ("3 2 2 2", "2"), ("5 -1 -1 -2 -2 -2", "-2"), ("4 5 5 4 4", "4"), ("1 0", "0")], ["Map обходит ключи от меньшего к большему.", "При равной частоте не меняйте уже найденный best."], "Первый ключ среди равных лучших частот окажется наименьшим.", headers="iostream map", difficulty=3),
                code("range", "Размах измерений", 'Ввод: n (1…100), n целых (−100…100). Выведите максимум минус минимум без изменения исходного порядка. Используйте один проход.', 'int n = 0, low = 0;\nstd::cin >> n >> low;\nint high = low;\nfor (int i = 1; i < n; ++i) {\n    int x = 0; std::cin >> x;\n    if (x < low) { low = x; }\n    if (x > high) { high = x; }\n}\nstd::cout << high - low;', [("4 -8 2 7 -3", "15"), ("1 9", "0"), ("3 5 5 5", "0"), ("4 -100 100 0 50", "200"), ("2 -1 -2", "1"), ("5 0 0 0 0 0", "0")], ["Первый элемент подходит как начальное значение обоих экстремумов.", "Сортировка для размаха не нужна."], "Выбор более простого алгоритма сохраняет данные и уменьшает подготовку.", difficulty=2),
                choice("stats", "Среднее и медиана", 'У набора 1,2,9 какие среднее и медиана?', ["Среднее 4, медиана 2", "Среднее 2, медиана 4", "Оба равны 9"], 0, ["Сумма равна 12, элементов три.", "После сортировки центральный элемент — 2."], "Различающие примеры помогают не перепутать определения показателей."),
                code("report", "Итоговый отчёт измерений", 'Ввод: нечётное n (1…99), затем n целых (−100…100). Выведите три строки: Count: n; Median: центральный элемент; Mean: среднее с 2 знаками. Точки с запятой здесь разделяют требования, не входят в вывод.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nlong long sum = 0;\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; sum += v[i]; }\nstd::sort(v.begin(), v.end());\nstd::cout << "Count: " << n << "\\nMedian: " << v[n / 2]\n          << "\\nMean: " << std::fixed << std::setprecision(2) << static_cast<double>(sum) / n;', [("3 1 2 9", "Count: 3\nMedian: 2\nMean: 4.00"), ("1 -5", "Count: 1\nMedian: -5\nMean: -5.00"), ("3 -5 0 5", "Count: 3\nMedian: 0\nMean: 0.00"), ("5 1 1 1 10 10", "Count: 5\nMedian: 1\nMean: 4.60"), ("1 0", "Count: 1\nMedian: 0\nMean: 0.00"), ("3 100 100 100", "Count: 3\nMedian: 100\nMean: 100.00")], ["Медиана и среднее требуют разных расчётов.", "Сумму можно накопить при чтении; для медианы нужен sort."], "Контракт нечётного n избегает дополнительного соглашения о двух центральных значениях.", headers="iostream vector algorithm iomanip", difficulty=3)
            ], ["проект", "статистика", "проверяемый отчёт"]),
        lesson("journalproject", "Проект: локальный журнал", "Проверьте данные до замены файла.",
            "Надёжная работа с файлом начинается с проверки входа. Если вход содержит ошибку, нельзя сначала уничтожить старый журнал, а потом сообщить Invalid. Сначала прочитайте и проверьте данные в памяти, затем открывайте файл для записи. Это ещё не полноценная атомарная запись: сбой во время перезаписи по-прежнему опасен. Для настоящего сохранения используют временный файл в той же файловой системе, проверку и атомарную замену средствами ОС. Учебная стандартная программа здесь демонстрирует только принцип проверки до изменения.\n\nВ примерах показываем начальное и ожидаемое содержимое файлов. Чтение, расчёт и запись — отдельные этапы. Не называйте файл сохранённым до успешного завершения записи и закрытия.",
            program('int n = 0;\nif (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "Invalid"; return 0; }\nstd::ofstream file("journal.txt");\nif (!file) { std::cout << "Error"; return 0; }\nfile << n << "\\n";\nfile.close();\nif (file) { std::cout << "Saved"; }\nelse { std::cout << "Error"; }', "iostream fstream"),
            "Гарантия «не менять файл при ошибочном входе» слабее гарантии «не терять старый файл при любой ошибке записи». Не смешивайте их в отчёте. Приложение codelib применяет атомарную запись Foundation и предыдущую копию; эти упражнения не выдают простой ofstream за такую же систему.",
            "Проверьте весь вход до открытия обрезающего ofstream. Различайте прикладную проверку, успешную запись и атомарность.", [
                code("validate", "Не трогайте старый журнал", 'Ввод: один токен, который читается как int n по правилам >>. Если чтение не удалось или n вне 0…100, выведите Invalid и не меняйте journal.txt. Иначе запишите n с переносом, проверьте close и выведите Saved/Error.', 'int n = 0;\nif (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "Invalid"; return 0; }\nstd::ofstream file("journal.txt");\nif (!file) { std::cout << "Error"; return 0; }\nfile << n << "\\n";\nfile.close();\nif (file) { std::cout << "Saved"; }\nelse { std::cout << "Error"; }', [dict(input="-1",output="Invalid",files={"journal.txt":"old\n"},expectedFiles={"journal.txt":"old\n"}), dict(input="7",output="Saved",expectedFiles={"journal.txt":"7\n"})], ["Проверка должна предшествовать созданию ofstream.", "Открытие обычного ofstream уже может обрезать старый файл."], "Проверяется конкретная гарантия: ошибочный вход не изменяет журнал.", headers="iostream fstream", difficulty=3),
                code("load", "Загрузите журнал", 'Файл journal.txt может отсутствовать. Если отсутствует — Missing. Если есть, он должен содержать ровно одно целое 0…100 и только пробелы вокруг. При нарушении — Invalid, иначе выведите число. Проверяйте весь оставшийся текст.', 'std::ifstream file("journal.txt");\nif (!file) { std::cout << "Missing"; return 0; }\nint n = 0; char extra = 0;\nif (!(file >> n) || (file >> extra) || n < 0 || n > 100) {\n    std::cout << "Invalid";\n} else { std::cout << n; }', [dict(input="",output="Missing"), dict(input="",output="7",files={"journal.txt":" 7\n"}), dict(input="",output="Invalid",files={"journal.txt":"7 8\n"}), dict(input="",output="Invalid",files={"journal.txt":"broken"})], ["После числа попробуйте прочитать ещё один непробельный char.", "Лишний символ или второе число должны сделать файл недопустимым."], "Проверка полной записи не принимает корректный префикс повреждённого файла.", headers="iostream fstream", difficulty=3),
                choice("atomic", "Честная гарантия", 'Гарантирует ли обычная запись ofstream с проверкой close сохранность старого файла при сбое посередине записи?', ["Нет, для атомарной замены нужны дополнительные механизмы", "Да, всегда", "Да, если имя файла короткое"], 0, ["Старый файл мог быть обрезан ещё при открытии.", "Проверка ошибки сообщает о проблеме, но не откатывает уже сделанные изменения."], "Не выдавайте обнаружение ошибки за транзакционность."),
                code("batch", "Проверка всего набора", 'Ввод: n и затем n целых. n должен быть 0…100, каждое число −100…100. При любом неуспешном чтении/нарушении выведите Invalid и не меняйте batch.txt. Иначе запишите все n чисел по одному в строке, проверьте close и выведите Saved/Error. Лишние токены после n чисел не анализируются.', 'int n = 0;\nif (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "Invalid"; return 0; }\nstd::vector<int> values(n);\nfor (int i = 0; i < n; ++i) {\n    if (!(std::cin >> values[i]) || values[i] < -100 || values[i] > 100) {\n        std::cout << "Invalid"; return 0;\n    }\n}\nstd::ofstream file("batch.txt");\nif (!file) { std::cout << "Error"; return 0; }\nfor (int x : values) { file << x << "\\n"; }\nfile.close();\nif (file) { std::cout << "Saved"; }\nelse { std::cout << "Error"; }', [dict(input="3 1 x 2",output="Invalid",files={"batch.txt":"old"},expectedFiles={"batch.txt":"old"}), dict(input="3 1 -2 3",output="Saved",expectedFiles={"batch.txt":"1\n-2\n3\n"}), dict(input="0",output="Saved",expectedFiles={"batch.txt":""})], ["Не открывайте файл внутри цикла проверки.", "Сначала заполните проверенный vector, потом запишите его целиком."], "Ошибка в середине набора не уничтожает прежние результаты.", headers="iostream vector fstream", difficulty=3)
            ], ["проект", "файлы", "сохранность данных"])
    ])]
